tions/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Side Kick","variant":"1 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Stikine","variant":"1 piece, bent shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Stikine","variant":"1 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Strike","variant":"1 piece, bent shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Strike","variant":"1 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Strike","variant":"4 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Surge","variant":"1 piece, bent shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Surge","variant":"1 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Surge","variant":"4 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, bent shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null},{"category":"paddle","brand":"Werner","model":"Twist","variant":"4 piece, straight shaft","availability":"current","availability_source":"https://web.archive.org/web/20250806142051/https://wernerpaddles.com/collections/whitewater","availability_checked":"2026-11-01","year_to":null}]$seed$::jsonb) AS s(
    category material_category, brand text, model text, variant text,
    availability material_availability, availability_source text,
    availability_checked date, year_to int
);

UPDATE materials m SET
    availability = s.availability,
    availability_source = s.availability_source,
    availability_checked = s.availability_checked,
    year_to = CASE WHEN m.year_to IS NULL AND s.year_to IS NOT NULL
                        AND (m.year_from IS NULL OR s.year_to >= m.year_from)
                   THEN s.year_to ELSE m.year_to END
FROM seed_availability s
WHERE m.category = s.category
  AND lower(btrim(m.brand)) = lower(btrim(s.brand))
  AND lower(btrim(m.model)) = lower(btrim(s.model))
  AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(s.variant, '')))
  AND m.created_by = 'system-catalogue'
  AND m.updated_by IS NULL
  AND (m.availability, m.availability_source, m.availability_checked, m.year_to)
      IS DISTINCT FROM (s.availability, s.availability_source, s.availability_checked,
          CASE WHEN m.year_to IS NULL AND s.year_to IS NOT NULL
                    AND (m.year_from IS NULL OR s.year_to >= m.year_from)
               THEN s.year_to ELSE m.year_to END);

DO $$
DECLARE missing int;
BEGIN
    SELECT COUNT(*) INTO missing FROM seed_availability s
    WHERE NOT EXISTS (
        SELECT 1 FROM materials m
        WHERE m.category = s.category
          AND lower(btrim(m.brand)) = lower(btrim(s.brand))
          AND lower(btrim(m.model)) = lower(btrim(s.model))
          AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(s.variant, ''))));
    RAISE NOTICE 'availability rows matching no entry: %', missing;
END $$;
